// Border-aware isotropic and multi-tap anisotropic sampling for WebGL 2.
ivec2 Q4BorderSize(sampler2D map, int level) {
    // Complete mip chains halve each dimension, rounding down to at least one.
    // Query only the uniform base level: some software drivers incorrectly
    // broadcast textureSize(map, varyingLevel) from the first fragment lane.
    return max(textureSize(map, 0) >> level, ivec2(1));
