vec4 Q4BorderTexel(sampler2D map, ivec2 texel, int level, vec4 border) {
    ivec2 size = Q4BorderSize(map, level);
    if (any(lessThan(texel, ivec2(0))) || any(greaterThanEqual(texel, size))) {
        return border;
    }
    return texelFetch(map, texel, level);
}

vec4 Q4BorderLevel(sampler2D map, vec2 uv, int level, vec4 border, bool linearFilter) {
    vec2 size = vec2(Q4BorderSize(map, level));
    // Bound huge finite coordinates before float-to-int conversion. Anything
    // beyond this interval has an entirely border-colored sampling footprint.
    vec2 position = clamp(uv * size, vec2(-1.0), size + vec2(1.0));
    if (!linearFilter) {
        return Q4BorderTexel(map, ivec2(floor(position)), level, border);
    }
    position -= vec2(0.5);
    ivec2 lower = ivec2(floor(position));
    vec2 weight = fract(position);
    vec4 top = mix(Q4BorderTexel(map, lower, level, border),
                   Q4BorderTexel(map, lower + ivec2(1, 0), level, border), weight.x);
    vec4 bottom = mix(Q4BorderTexel(map, lower + ivec2(0, 1), level, border),
                      Q4BorderTexel(map, lower + ivec2(1, 1), level, border), weight.x);
    return mix(top, bottom, weight.y);
}

vec4 Q4BorderIsotropic(sampler2D map, vec2 uv, vec4 border, int filterMode, float lod, int lastLevel) {
    if (filterMode != 2) {
        return Q4BorderLevel(map, uv, 0, border, filterMode == 1);
    }
    float clampedLod = clamp(lod, 0.0, float(lastLevel));
    int lower = int(floor(clampedLod));
    int upper = min(lower + 1, lastLevel);
    return mix(Q4BorderLevel(map, uv, lower, border, true),
               Q4BorderLevel(map, uv, upper, border, true), fract(clampedLod));
}

vec4 Q4BorderGradient(sampler2D map, vec2 uv, vec4 border, int filterMode,
                      vec2 dx, vec2 dy, int lastLevel) {
    vec2 size = vec2(textureSize(map, 0));
    vec2 texelDx = dx * size, texelDy = dy * size;
    float footprintSquared = max(dot(texelDx, texelDx), dot(texelDy, texelDy));
    float lod = 0.5 * log2(max(footprintSquared, 0.000000000001));
    return Q4BorderIsotropic(map, uv, border, filterMode, lod, lastLevel);
}

vec4 Q4BorderAnisotropic(sampler2D map, vec2 uv, vec4 border, int filterMode,
                         vec2 dx, vec2 dy, int lastLevel, float maxAnisotropy) {
