        return Q4BorderTexel(map, ivec2(floor(position)), level, border);
    }
    position -= vec2(0.5);
    ivec2 lower = ivec2(floor(position));
    vec2 weight = fract(position);
    vec4 top = mix(Q4BorderTexel(map, lower, level, border),
                   Q4BorderTexel(map, lower + ivec2(1, 0), level, border), weight.x);
    vec4 bottom = mix(Q4BorderTexel(map, lower + ivec2(0, 1), level, border),
                      Q4BorderTexel(map, lower + ivec2(1, 1), level, border), weight.x);
    return mix(top, bottom, weight.y);
